// P18 로컬 골격: STORAGE-DESIGN 4절과 6.1의 DLQ 계약만 검사한다.
// 저장소와 운영 재처리 드라이버가 연결되기 전에는 보관·claim·resolve 성공을 반환하지 않는다.
const input = $json;
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const isText = (v) => typeof v === 'string' && v.trim().length > 0;
const isNullableText = (v) => v === null || isText(v);
const hasOwn = (v, key) => Object.prototype.hasOwnProperty.call(v, key);
const hasOnlyKeys = (v, allowed) => isObj(v) && Object.keys(v).every((key) => allowed.has(key));
const allowedStatuses = new Set(['confirmed', 'none', 'failed', 'unknown']);
const allowedActions = new Set(['create', 'bind', 'context_update', 'close', 'assign', 'alert', 'finish', 'inspect_only']);
const forbiddenKey = /(url|endpoint|code|script|credential|token|password|secret|authorization)/i;

const containsForbiddenKey = (value) => {
  if (Array.isArray(value)) return value.some(containsForbiddenKey);
  if (!isObj(value)) return false;
  return Object.entries(value).some(([key, child]) => forbiddenKey.test(key) || containsForbiddenKey(child));
};

const isEffect = (v) => {
  if (!hasOnlyKeys(v, new Set(['status', 'id', 'error_code']))) return false;
  if (!allowedStatuses.has(v.status)) return false;
  if (hasOwn(v, 'id') && !isText(v.id)) return false;
  return !hasOwn(v, 'error_code') || v.error_code === null || isText(v.error_code);
};

const isEffects = (v) => {
  const keys = new Set(['created_or_reused', 'context_saved', 'closed', 'assigned', 'alert']);
  return hasOnlyKeys(v, keys) && [...keys].every((key) => hasOwn(v, key) && isEffect(v[key]));
};

const isRecovery = (v) => {
  if (!hasOnlyKeys(v, new Set(['version', 'mode', 'action', 'args', 'reference', 'reason']))) return false;
  if (v.version !== 1 || !['payload', 'jira_ref', 'manual_required'].includes(v.mode) || !allowedActions.has(v.action)) return false;
  if (!(v.reason === null || typeof v.reason === 'string')) return false;
  if (containsForbiddenKey(v.args) || containsForbiddenKey(v.reference)) return false;
  if (v.mode === 'payload') return isObj(v.args) && v.reference === null;
  if (v.mode === 'jira_ref') return v.args === null && isObj(v.reference) && isText(v.reference.jira_issue_id) && isText(v.reference.case_id) && isText(v.reference.owner_id);
  return v.args === null && v.reference === null;
};

const validatePut = (v) => {
  const keys = new Set(['op', 'scope', 'request_id', 'case_id', 'jira_issue_id', 'jira_issue_key', 'failed_step', 'error_code', 'summary', 'attempts', 'effects', 'recovery', 'last_execution_id']);
  return hasOnlyKeys(v, keys) && [...keys].every((key) => hasOwn(v, key)) && v.op === 'put' && isText(v.scope) && isNullableText(v.request_id) && isNullableText(v.case_id) && isNullableText(v.jira_issue_id) && isNullableText(v.jira_issue_key) && isText(v.failed_step) && isText(v.error_code) && isText(v.summary) && Number.isInteger(v.attempts) && v.attempts >= 0 && isEffects(v.effects) && isRecovery(v.recovery) && isNullableText(v.last_execution_id);
};

const validateClaim = (v) => hasOnlyKeys(v, new Set(['op', 'scope', 'dlq_id', 'expected_revision', 'operator_id', 'execution_id'])) && v.op === 'claim' && isText(v.scope) && isText(v.dlq_id) && Number.isInteger(v.expected_revision) && v.expected_revision >= 0 && isText(v.operator_id) && isText(v.execution_id);
const validateResolve = (v) => hasOnlyKeys(v, new Set(['op', 'scope', 'dlq_id', 'expected_revision', 'operator_id', 'execution_id', 'resolution'])) && v.op === 'resolve' && isText(v.scope) && isText(v.dlq_id) && Number.isInteger(v.expected_revision) && v.expected_revision >= 0 && isText(v.operator_id) && isText(v.execution_id) && isText(v.resolution);

const validators = { put: validatePut, claim: validateClaim, resolve: validateResolve };
const valid = isObj(input) && isText(input.op) && hasOwn(validators, input.op) && validators[input.op](input);
return [{ json: {
  ok: false,
  dlq_id: null,
  deduplicated: false,
  error_code: valid ? 'dlq_backend_unconfigured' : 'invalid_dlq_request'
} }];
